"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[70731],{54162:e=>{e.exports=JSON.parse('{"title":"Agent Error Simulator: Fault Injection for Testing in Agentic Workflows","authors":["K. Bateman","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"The 22nd IEEE International Conference on eScience (eScience\'26)","type":"Conference","date":"September, 2026","month":9,"year":2026,"doi":"10.1109/eScience70237.2026.00052","tags":["AI","LLM Agents","Agentic Workflows","Fault Injection","Fault Tolerance","Benchmarking"],"links":{"pdf":"http://cs.iit.edu/~scs/assets/files/bateman2026agenterrorsimulator.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/bateman2026agenterrorsimulator.bib","citation":"http://cs.iit.edu/~scs/assets/files/bateman2026agenterrorsimulator.txt"},"abstract":"Multi-agent large language model workflows are increasingly deployed for complex, multi-step computational tasks, yet their fault tolerance remains poorly characterized. We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection. AES intercepts agent-to-model HTTP traffic via a transparent proxy and injects format, logic, and tool-call faults at configurable points in a hierarchical planner-worker-aggregator workflow. We evaluate four models spanning 2B to 32B parameters across 194 jobs in ten test groups covering baseline behavior, multi-error injection, workflow scale, context pressure, compaction, and detection timing. The results reveal a model-size-dependent logic-error recovery threshold between 7B and 27B parameters, universal catastrophic failure under aggregator-level logic injection, and model-specific aggregator arithmetic deficits that interact with injected faults. We release the benchmark suite, injection tooling, and result data to support reproducible multi-agent fault-tolerance research.","slug":"bateman-2026-agent-error-simulator-3c7d"}')}}]);